var suggestions=document.getElementById('suggestions'),search=document.getElementById('search');search!==null&&document.addEventListener('keydown',inputFocus);function inputFocus(a){a.ctrlKey&&a.key==='/'&&(a.preventDefault(),search.focus()),a.key==='Escape'&&(search.blur(),suggestions.classList.add('d-none'))}document.addEventListener('click',function(a){var b=suggestions.contains(a.target);b||suggestions.classList.add('d-none')}),document.addEventListener('keydown',suggestionFocus);function suggestionFocus(c){const d=suggestions.classList.contains('d-none');if(d)return;const a=[...suggestions.querySelectorAll('a')];if(a.length===0)return;const b=a.indexOf(document.activeElement);if(c.key==="ArrowUp"){c.preventDefault();const d=b>0?b-1:0;a[d].focus()}else if(c.key==="ArrowDown"){c.preventDefault();const d=b+1<a.length?b+1:b;a[d].focus()}}(function(){var a=new FlexSearch.Document({tokenize:"forward",cache:100,document:{id:'id',store:["href","title","description"],index:["title","description","content"]}});a.add({id:0,href:"/docs/introduction/welcome/",title:"Welcome",description:"AppservR is an open-source program to deploy R Shiny apps on Windows and Linux easily.",content:"Get started # AppservR can be downloaded from GitHub (pick a download option for the latest release for your platform). Download →\nDownload\nOur one-page Quick Start tutorial will help you get started. Quick Start →\nGo further # Get instructions on how to accomplish common tasks with AppservR. Recipes →\nContributing # We welcome very much contributions and feedback on this project. Please feel free to contribute, starting by opening an issue on GitHub to report a bug or discuss features. Contributing →\nHelp # Get help on AppservR. Help →\n"}).add({id:1,href:"/docs/introduction/quick-start/",title:"Quick Start",description:"A one page tutorial to use AppservR.",content:"Requirements # AppservR runs your Shiny apps using your system installation of R. You need to have R installed on your system to use it. You will also need the shiny package and all other R packages your apps need. Learn more about Shiny →\n💡  Make sure first that you are able to run your Shiny app properly using R/Rstudio to check that all required packages are installed.   AppservR itself ships as prebuilt binaries for Windows (32 and 64-bit) and Linux (64-bit). There\u0026rsquo;s no macOS build at the moment.\nDownload \u0026amp; Install # Get the latest AppservR executable for your platform on Github. You will need to choose the download option suited to your platform.\nDownload\nTo install, just uncompress the archive at a location of your choice.\nRun # AppservR is a command-line program with a web graphical user interface. Most settings can be configured using only the web interface, which means that you do not need to access the server to configure a new Shiny app.\nStart a terminal window in the directory where AppservR executable file is and then type:\n./appservR serve  Go to http://localhost:8080. You should see a running sample app (the classic Shiny\u0026rsquo;s Old Faithful Geyser Data, with a twist: it also displays the username of whoever is logged in, see Manage user authentication →). If not, see below.\nConfigure # When you run AppservR for the first time, it will create in the same directory as the executable file:\n a config.yml configuration file, an apps folder containing a sample Shiny app, a SQLite database file holding apps and users settings.  Settings which require restarting the server to take effect are defined in the config.yml file. Other settings can be changed via the web interface.\nConfiguration file # config.yml configuration file is created in the same directory as the executable file, and allows setting the port and host to listen on, the location of the Rscript executable, etc. It is populated with default settings which should work for most users. See the full list of settings in Configuration reference →.\nIn particular, AppservR will look for the Rscript executable at the default installation location for your platform. If it is installed elsewhere, you will not see the sample app when navigating to http://localhost:8080, and you should set the appropriate location in the config.yml file.\nWeb interface # Go to http://localhost:8080/admin to access the admin interface.\nYou will first need to register as a user via the login \u0026gt; signup form. The first user to sign up is registered as an admin user.\nAfter you have created your admin account and successfully logged in, you can configure existing or new Shiny apps at http://localhost:8080/admin/apps. Several apps can live on the same server and be accessed using the path you configure. See Configure your first app → for a walkthrough of the form.\nOn each app configuration page you can also see the console output of the R session used to run your app, which can be useful to troubleshoot issues.\nGo further # Check our tutorials on more advanced uses of AppservR. Recipes →\n"}).add({id:2,href:"/docs/recipes/configure-first-app/",title:"Configure your first app",description:"Walkthrough of the app configuration form: name, path, access control, source directory, and workers.",content:"Once you\u0026rsquo;re logged in as an admin, go to http://localhost:8080/admin/apps and click New App. This walks through each field on that form.\n  Main settings #    Name of the app: letters, numbers, hyphens, and underscores only. This is also the name shown on the apps list. Path of the app: where the app is served, for example /sales-dashboard. It must start with / and can\u0026rsquo;t be /admin or /auth, since those are reserved for AppservR itself. Several apps can share the same server on different paths, including nested ones (/ and /sales-dashboard and /sales-dashboard/internal can all coexist). Is active: unchecked apps are configured but not running, and won\u0026rsquo;t use any of your R workers. Grant access to: who can reach the app once it\u0026rsquo;s active.  Everyone: public, no login required. All authenticated users: any user who signed up on this AppservR instance. Specific user groups: pick from the groups you\u0026rsquo;ve created under the Groups tab.    App source # AppservR currently only supports a local or network directory as an app\u0026rsquo;s source: a path to a folder containing either app.R, or both server.R and ui.R. This can be a path on the machine AppservR runs on, or a network share it can read. A Git repository source is planned but not available yet, which is why that option is disabled in the form.\nServing # Number of process workers sets how many separate Rscript processes AppservR keeps running for this app, side by side. A user session is bound to one worker for its whole duration, but a single worker serves multiple sessions at once: new sessions are routed to whichever running worker currently has the fewest connected users. Sharing workers this way is what makes AppservR resource-efficient — most apps don\u0026rsquo;t need one process per user.\nHow many workers to configure depends less on how many users you expect and more on what the app actually does once someone\u0026rsquo;s connected. R itself is single-threaded, so while a worker is busy computing something for one of its sessions, every other session sharing that worker has to wait its turn. For apps that respond quickly (most dashboards and interactive tools), a handful of sessions can comfortably share one worker. For apps with long-running CPU-bound operations in the main reactive context, and that don\u0026rsquo;t use an async pattern (the future/promises packages) to run that work in the background, one slow computation blocks every other session on that worker, so you\u0026rsquo;ll want a worker count closer to your expected number of concurrent users.\nAfter saving # Once saved, the app\u0026rsquo;s own page shows the console output of each running worker, which is the first place to look if an app isn\u0026rsquo;t starting (see the \u0026ldquo;Listening on\u0026rdquo; line below, confirming the worker actually started).\n  "}).add({id:3,href:"/docs/recipes/customize-styling/",title:"Customize styling",description:"Built-in pages (login, etc.) can be customized to match your image.",content:"Customize html templates # All built-in pages, such as signup, login, error pages, are embedded in AppservR\u0026rsquo;s executable. However, they can be changed easily if you want to translate them to your language, add your company\u0026rsquo;s logo, etc.\nYou just need to create a templates directory at the same location as the executable file. AppservR will look for existing files in this directory before falling back to the default templates.\nPlease check out this folder on Github and download the template files that you want to modify in your local templates folder (keeping the exact same subdirectories and filenames). The template engine is Go\u0026rsquo;s default template package. Please check out their doc to learn about the syntax. However, you would likely just need to modify the html.\nAdd/modify static files # In a similar way as the templates folder, you can create an assets folder at the same location as AppservR executable. Static files will be looked up in this directory, fall back to default bundle files if they do not exist, and return a 404 not found error if the file is not present neither in your local assets folder nor in the default bundled assets folder.\nThis can be useful to add external javascript, css or images.\nThe content of the assets folder is served under the /assets/ url path.\nBeware that static files will be served to all users, and you cannot manage access to this folder.\n"}).add({id:4,href:"/docs/recipes/manage-auth/",title:"Manage user authentication",description:"AppservR manages user authentication and access restriction to your apps.",content:"Manage users # You can create new users via the admin interface, or users can sign up themselves.\nUsers belong to groups that you can create through the admin interface. By default, the first user to sign up belongs to the admins group. The admins group cannot be renamed nor removed, and admin users cannot remove themselves from this group.\nAccess control # You can control who is allowed to access each app:\n Everyone All authenticated users Users belonging to specific groups  This setting can be found in each app page in the admin interface.\nGet authenticated user from your app # Your R app can be aware of the authentication infos for the current user, if any. This information is accessible in the HTTP headers sent to your app by the AppservR proxy.\nThe default app (Old Faithful Geyser Data) demonstrates how to use this information to identify the user currently logged in.\nFrom Shiny, username and displayed name can be accessed from your server function as follows:\nserver \u0026lt;- function(input, output, session) { output$username \u0026lt;- renderText({ if (exists(\u0026quot;HTTP_APPSERVR_USERNAME\u0026quot;, envir=session$request)) { get(\u0026quot;HTTP_APPSERVR_USERNAME\u0026quot;, envir=session$request) } else { \u0026quot;unknown\u0026quot; } }) output$displayed_name \u0026lt;- renderText({ if (exists(\u0026quot;HTTP_APPSERVR_DISPLAYEDNAME\u0026quot;, envir=session$request)) { get(\u0026quot;HTTP_APPSERVR_DISPLAYEDNAME\u0026quot;, envir=session$request) } else { \u0026quot;unknown\u0026quot; } }) ... }  "}).add({id:5,href:"/docs/recipes/install-service/",title:"Install as a service",description:"AppservR can be installed as a service to run automatically in the background.",content:"Manage service via the CLI # The ./appservR service command allows installing and managing the AppservR service on Windows and Linux.\n💡  Managing services requires to run a command prompt as admin on Windows.   Install # ./appservR service install sub-command installs AppservR as a service (running the executable file at its current location).\nOn Windows, only admins can install services, and services run with administrative privileges by default. We recommend that you change this, using the services configuration panel after install, in order to have it run by a non-admin account. Otherwise, you allow AppservR admins to run arbitrary scripts as admin, which is a security threat (AppservR uses your system installation of R and is not isolated from your system).\nStart # ./appservR service start starts the service.\nStop # ./appservR service stop stops the service.\nUninstall # ./appservR service remove uninstalls the service if it is already stopped, or schedules its removal for right after it stops.\nRun without admin rights on Windows # Without admin privilege you cannot install AppservR as a service on Windows. However, you can still run it as a scheduled task to run on startup or at session start, which should be a decent alternative in most cases.\n"}).add({id:6,href:"/docs/recipes/configuration-reference/",title:"Configuration reference",description:"Every config.yml setting and command-line flag AppservR reads.",content:"config.yml is written next to the executable the first time you run AppservR, populated with defaults. Settings here need a server restart to take effect; everything else (apps, users, groups, access control) is managed live through the admin web interface.\nSettings #    Key Default Description     server.host localhost Address to listen on. Set to 0.0.0.0 to accept connections from other machines.   server.port 8080 Port to listen on.   RScript Rscript on Linux, auto-detected under C:/Program Files/R on Windows Path to the Rscript executable used to launch Shiny apps. Set this explicitly if R isn\u0026rsquo;t in a standard location, or if you want to point at a specific R installation.   database.path \u0026lt;executable folder\u0026gt;/data.db Path to the SQLite database file holding apps, users, and groups.   mode prod prod logs at WARNING level; debug logs at DEBUG level.    database.type also exists in the file but sqlite is the only backend AppservR supports today, so it shouldn\u0026rsquo;t be changed.\nCommand-line flags # The serve command accepts flags that override the corresponding config.yml setting for that run, without writing them back to the file:\n./appservR serve -a 0.0.0.0 -p 9090 -m debug     Flag Long form Overrides     -a --address server.host   -p --port server.port   -m --mode mode    Environment variables #    Variable Effect     APPSERVR_AUTH_SECRET Signing secret for login sessions. See Running in production → for why you\u0026rsquo;ll want to set this.    "}).add({id:7,href:"/docs/recipes/production-considerations/",title:"Running in production",description:"Session persistence, backups, and upgrading an AppservR install.",content:"Login sessions # Logins last 15 minutes, and by default that clock resets for everyone the moment the server restarts: AppservR signs login sessions with a random secret generated when the process starts, so restarting the service invalidates every session that was still active, forcing a fresh login.\nTo keep sessions valid across restarts, set the APPSERVR_AUTH_SECRET environment variable to a fixed value before starting AppservR (as a service, this is set in the service\u0026rsquo;s environment, not in config.yml). Any long random string works; the important part is that it stays the same across restarts and isn\u0026rsquo;t shared outside your team.\nData and backups # Everything AppservR needs to restore an install lives in two places next to the executable:\n config.yml, the server configuration. the SQLite database file (data.db by default, see Configuration reference → for how to change its location), holding every app, user, and group.  Your apps' own R source directories are wherever you pointed each app\u0026rsquo;s Shiny app directory field, so back those up too if they aren\u0026rsquo;t already under version control elsewhere.\nUpgrading # To upgrade, stop the service, replace the executable with the new version, and start it again. config.yml and the database file are untouched by the upgrade itself; AppservR runs its database migrations automatically on startup, so there\u0026rsquo;s no separate migration step to run.\nAs always, back up the database file before upgrading across a major version.\n"}).add({id:8,href:"/docs/help/faq/",title:"FAQ",description:"Answers to frequently asked questions.",content:"Why am I logged out every time the server restarts? # By default, AppservR signs login sessions with a secret it generates fresh each time it starts, so every restart invalidates existing sessions. Set the APPSERVR_AUTH_SECRET environment variable to a fixed value to keep sessions valid across restarts. See Running in production →.\nCan I deploy an app straight from a Git repository? # Not yet. The admin UI has a \u0026ldquo;Git repository\u0026rdquo; option in the app source picker, but it\u0026rsquo;s disabled and marked \u0026ldquo;not available yet\u0026rdquo; — only a local or network directory works today. See Configure your first app →.\nWhat platforms does AppservR run on? # Prebuilt binaries are published for Windows (32 and 64-bit) and Linux (64-bit). There\u0026rsquo;s no macOS build.\nMy app isn\u0026rsquo;t showing up, or seems stuck. Where do I look? # Each app\u0026rsquo;s own page in the admin interface (/admin/apps/\u0026lt;name\u0026gt;) shows the console output of its running R workers. A worker that started successfully prints a \u0026ldquo;Listening on\u0026rdquo; line; anything else printed there (an R error, a missing package) is usually the actual cause. See Configure your first app →.\nCan several apps run on the same server? # Yes. Each app gets its own path, and paths can be nested (/ and /sales-dashboard and /sales-dashboard/internal can all coexist). Each app also runs its own R worker processes, independent from every other app\u0026rsquo;s.\nHow do I move AppservR to a new server, or back it up? # Back up config.yml and the SQLite database file next to the executable, plus whichever directories your apps' source code lives in. See Running in production →.\n"}).add({id:9,href:"/docs/help/about/",title:"About",description:"About AppservR",content:"Why this project? # There are already some alternatives to deploy R Shiny apps:\n shinyapps.io is Posit\u0026rsquo;s own hosted service: no server to manage at all, but you don\u0026rsquo;t control the environment and usage is metered. Shiny Server (the free, open-source edition) is self-hosted like AppservR, but Linux-only, and has no built-in authentication (that\u0026rsquo;s a Shiny Server Pro feature). ShinyProxy runs each user session in its own Docker container, which is powerful for isolation and scaling, but means taking on a Docker deployment to get there.  and maybe some others.\nAppservR\u0026rsquo;s trade-off is different: a single cross-platform binary with authentication built in and no container runtime required, at the cost of some of the isolation and scaling headroom those other tools offer.\nHowever, working in an organization where data is not the primary focus and with limited IT admin resources (100% Windows!), I found no easy way to share Shiny apps internally as proof of concept.\nAppservR is intended as a solution for simple deployment with limited admin resources, without conceding performance.\nAlso it was a fun project to start with the Go programming language during COVID-19 lockdowns weekends.\nAbout this website # This documentation website was built using Doks, an amazing theme for Hugo.\nYou can contribute if you think that some content is missing clarity etc. on this GitHub repository.\n"}).add({id:10,href:"/docs/help/",title:"Help",description:"Get help.",content:""}).add({id:11,href:"/docs/introduction/",title:"Introduction",description:"Introduction to AppservR",content:""}).add({id:12,href:"/docs/recipes/",title:"Recipes",description:"Manual to perform common tasks with AppservR",content:""}).add({id:13,href:"/docs/",title:"Docs",description:"Documentation for AppservR.",content:""}),search.addEventListener('input',b,!0);function b(){var b,e;const d=5;b=this.value,e=a.search(b,{limit:d,enrich:!0});const c=new Map;for(const a of e.flatMap(a=>a.result)){if(c.has(a.doc.href))continue;c.set(a.doc.href,a.doc)}if(suggestions.innerHTML="",suggestions.classList.remove('d-none'),c.size===0&&b){const a=document.createElement('div');a.innerHTML=`No results for "<strong>${b}</strong>"`,a.classList.add("suggestion__no-results"),suggestions.appendChild(a);return}for(const[h,g]of c){const b=document.createElement('div');suggestions.appendChild(b);const a=document.createElement('a');a.href=h,b.appendChild(a);const e=document.createElement('span');e.textContent=g.title,e.classList.add("suggestion__title"),a.appendChild(e);const f=document.createElement('span');if(f.textContent=g.description,f.classList.add("suggestion__description"),a.appendChild(f),suggestions.appendChild(b),suggestions.childElementCount==d)break}}})()